cat > s4.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(800);
await p.goto('http://127.0.0.1:54569/billing');
await p.waitForTimeout(800);
const f = p.frameLocator('iframe[title="Billing panel"]');
await f.locator('plan-picker').getByLabel('Annual').check().catch(e=>console.log('check err', e.message.slice(0,200)));
await f.locator('plan-picker').locator('#seats').fill('10').catch(e=>console.log('fill err', e.message.slice(0,200)));
await f.locator('plan-picker').getByRole('button',{name:'Confirm plan'}).click().catch(e=>console.log('click err', e.message.slice(0,200)));
await p.waitForTimeout(800);
const fr = p.frames().find(x=>x.url().includes('/widgets/plan'));
console.log(await fr.evaluate(()=>document.querySelector('plan-picker')?.shadowRoot ? 'open' : 'closed-or-none'));
await p.screenshot({path:'out.png'});
await b.close();
EOF
