cat > s5.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage({viewport:{width:1200,height:800}});
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForTimeout(800);
await p.goto('http://127.0.0.1:54569/billing');
await p.waitForTimeout(800);
const el = await p.$('iframe[title="Billing panel"]');
await el.click({position:{x:250,y:250}}); // focus body of frame (empty area)
await p.keyboard.press('Shift+Tab'); // try to land on radios
await p.keyboard.press('Tab');
await p.keyboard.press('ArrowDown'); // Monthly -> Annual
await p.keyboard.press('Tab');       // seats input
await p.keyboard.press('Control+A');
await p.keyboard.type('10');
await p.keyboard.press('Tab');       // confirm button
await p.keyboard.press('Enter');
await p.waitForTimeout(800);
const fr = p.frames().find(x=>x.url().includes('/widgets/plan'));
console.log(await fr.evaluate(()=>document.body.innerHTML.slice(0,200)));
await p.screenshot({path:'out.png'});
await b.close();
EOF
